\begin{document}
\begin{center}
{\LARGE Daniel Reyes}\\[3pt]
Mechanical Engineering, B.S. candidate\\
dreyes@example.edu \quad (555) 014-2287 \quad Portland, OR
\end{center}
\vspace{6pt}
\section*{Summary}
Senior mechanical engineering student seeking a design or manufacturing role.
Hands-on experience with CAD, prototyping, and shop fabrication.
Comfortable working across design, testing, and documentation.
\section*{Education}
\textbf{Oregon State University}, B.S. Mechanical Engineering, expected June 2026\\
GPA: 3.7/4.0, minor in Mathematics\\
Relevant coursework: Thermodynamics, Fluid Mechanics, Machine Design,\\
Heat Transfer, Control Systems, Finite Element Analysis
\section*{Experience}
\textbf{Mechanical Engineering Intern}, Meridian Auto Parts, Summer 2025
\begin{itemize}
\item Responsible for CAD modeling of bracket components in SolidWorks.
\item Helped with vibration testing of prototype mounts, cutting field failure rate by 12\%.
\item Worked on thermal simulations in ANSYS across 3 product lines.
\item Did drawing updates and documentation for the assembly line.
\end{itemize}
\textbf{Machine Shop Assistant}, University Fabrication Lab, 2024--2025
\begin{itemize}
\item Assisted students with lathe and mill operation during open shop hours.
\item Responsible for training 5 new interns on lab safety procedures.
\item Helped organize the SAE student chapter workshop with 120+ attendees.
\end{itemize}
\textbf{Manufacturing Intern}, Cascade Precision, Summer 2024
\begin{itemize}
\item Worked on inspection reports for 200+ machined parts per week.
\item Helped the quality team gauge incoming aluminum stock.
\item Did data entry for the tool calibration log.
\end{itemize}
\section*{Projects}
\textbf{Senior Capstone: Low-Cost Prosthetic Knee}, 2025--2026
\begin{itemize}
\item Led a 4-person team from concept review to final prototype.
\item Machined 15 prototype joints on the manual mill and lathe.
\item Presented design results at the regional ASME showcase.
\end{itemize}
\section*{Certifications}
Fundamentals of Engineering (FE) exam, passed 2025\\
SolidWorks CSWA, 2024\\
OSHA 10-hour general industry, 2024
\section*{Skills}
CAD: SolidWorks, Fusion 360, AutoCAD\\
Simulation: ANSYS Mechanical, Abaqus\\
Programming: MATLAB, Python (NumPy, pandas)\\
Fabrication: manual mill and lathe, MIG welding, 3D printing\\
Languages: English (native), Spanish (conversational)
\section*{Awards}
First place, ASME student design competition, 2025\\
Dean's list, six terms
\end{document}
